                continue
            if x is None:
                c = -1 if nulls_first else 1
            elif y is None:
                c = 1 if nulls_first else -1
            elif x == y:
                continue
            else:
                c = -1 if x < y else 1
            return -c if desc else c
        return 0

    return [r for _, r in sorted(rows, key=cmp_to_key(compare))]

