from datetime import datetime

DATE_TOKENS = ("YYYY", "MM", "DD", "M", "D")
DATETIME_TOKENS = ("YYYY", "MM", "DD", "HH", "hh", "mm", "ss", "M", "D", "H", "h", "A")


def group_digits(digits: str, sep: str, sizes, min_grouping: int) -> str:
    """Section 7.3: group the integer digits from the right."""
    if len(digits) < sizes[0] + min_grouping:
        return digits
    groups = []
    i = 0
    while len(digits) > 0:
        size = sizes[min(i, len(sizes) - 1)]
        groups.append(digits[-size:])
        digits = digits[:-size]
        i += 1
    return sep.join(reversed(groups))


def number_text(value, scale: int, locale, grouping: bool) -> str:
    text = f"{abs(value):.{scale}f}" if scale else str(abs(value))
    whole, _, frac = text.partition(".")
    negative = value < 0 and any(c != "0" for c in whole + frac)
    if locale is None:
        return ("-" if negative else "") + text
    if grouping:
        whole = group_digits(whole, locale.group, locale.group_sizes, locale.min_grouping)
    body = whole + (locale.decimal + frac if scale else "")
    return (locale.minus if negative else "") + body


def pattern_text(value, pattern: str) -> str:
    """A date or datetime written with a locale pattern (section 7.4)."""
    is_dt = isinstance(value, datetime)
    tokens = DATETIME_TOKENS if is_dt else DATE_TOKENS
    out = []
    i = 0
    while i < len(pattern):
        tok = next((t for t in sorted(tokens, key=len, reverse=True) if pattern.startswith(t, i)), None)
